//! `only_protobuf::well_known` is generated by this crate from its built-in `.proto` files; the
//! checked-in copy must match. After a generator change: `ONLY_PROTOBUF_BLESS=1 cargo test -p
//! only-protobuf-build --test well_known`.

use std::path::Path;

#[test]
fn well_known_types_are_up_to_date() {
    let target =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../only-protobuf/src/well_known/generated.rs");
    let names = [
        "google/protobuf/any.proto",
        "google/protobuf/api.proto",
        "google/protobuf/descriptor.proto",
        "google/protobuf/duration.proto",
        "google/protobuf/empty.proto",
        "google/protobuf/field_mask.proto",
        "google/protobuf/struct.proto",
        "google/protobuf/source_context.proto",
        "google/protobuf/timestamp.proto",
        "google/protobuf/type.proto",
        "google/protobuf/wrappers.proto",
    ];
    // The empty include directory names the inputs by their full import path; the built-in
    // sources are used, nothing is read from disk.
    let out = only_protobuf_build::Config::new()
        .include("")
        .compile_well_known_types(true)
        .unknown_fields(false)
        .generate(&names)
        .unwrap();
    assert_eq!(out.len(), 1);
    assert_eq!(out[0].0, "google.protobuf.rs");
    let code = &out[0].1;
    if std::env::var_os("ONLY_PROTOBUF_BLESS").is_some() {
        std::fs::write(&target, code).unwrap();
        return;
    }
    let Ok(have) = std::fs::read_to_string(&target) else {
        return; // not in the workspace (a published crate)
    };
    assert!(
        have == *code,
        "{} is stale: run ONLY_PROTOBUF_BLESS=1 cargo test -p only-protobuf-build --test well_known",
        target.display()
    );
}
